package com.example.simpleclient;
import com.fasterxml.jackson.databind.*;import javafx.application.Platform;import javafx.fxml.FXML;import javafx.scene.control.Label;import java.net.URI;import java.net.http.*;
public class AdminDashboardController{@FXML private Label totalCarsLabel,availableCarsLabel,unavailableCarsLabel,dashboardStatusLabel,totalCustomersLabel,totalBookingsLabel,revenueLabel,activeRentalsLabel,maintenanceCarsLabel;private final HttpClient h=HttpClient.newHttpClient();private final ObjectMapper m=new ObjectMapper();@FXML private void initialize(){loadDashboard();}@FXML private void refreshDashboard(){loadDashboard();}private void loadDashboard(){dashboardStatusLabel.setText("Refreshing live operations...");new Thread(()->{try{String t=AdminSession.getToken();HttpRequest sr=HttpRequest.newBuilder(URI.create("http://localhost:8080/api/admin/summary")).header("Authorization","Bearer "+t).GET().build();HttpRequest cr=HttpRequest.newBuilder(URI.create("http://localhost:8080/api/cars")).GET().build();JsonNode s=m.readTree(h.send(sr,HttpResponse.BodyHandlers.ofString()).body());JsonNode cars=m.readTree(h.send(cr,HttpResponse.BodyHandlers.ofString()).body());int av=0,maint=0;for(JsonNode c:cars){String st=c.path("status").asText("");if(st.isBlank()||"AVAILABLE".equalsIgnoreCase(st))av++;if("MAINTENANCE".equalsIgnoreCase(st))maint++;}int fav=av,un=cars.size()-av,fmaint=maint;Platform.runLater(()->{totalCarsLabel.setText(s.path("cars").asText());availableCarsLabel.setText(String.valueOf(fav));unavailableCarsLabel.setText(String.valueOf(un));totalCustomersLabel.setText(s.path("customers").asText());totalBookingsLabel.setText(s.path("bookings").asText());activeRentalsLabel.setText(s.path("activeRentals").asText());maintenanceCarsLabel.setText(String.valueOf(fmaint));revenueLabel.setText(String.format("RM %.0f",s.path("revenue").asDouble()));dashboardStatusLabel.setText("Live data • cars, customers, rentals and revenue");});}catch(Exception e){Platform.runLater(()->dashboardStatusLabel.setText("Unable to connect to backend."));}}).start();}}
